  (85566, '6ce8add8-1bf6-4095-a3dd-e7926cbcfd5e'::uuid, 'SACCHAROMYCES/LEUCONOSTOC/APPLE FRUIT/CARROT ROOT/RADISH ROOT/CABBAGE LEAF/CELERY LEAF/CUCUMBER FRUIT/BANANA FRUIT/ONION BULB/ARCTIUM LAPPA ROOT/SPINACH LEAF/ ORANGE PEEL/TOMATO FRUIT/PHASEOLUS RADIATUS SPROUT/PUMPKIN FRUIT EXTRACT FERMENT FILTRATE', 'Saccharomyces/Leuconostoc/Apple Fruit/Carrot Root/Radish Root/Cabbage Leaf/Celery Leaf/Cucumber Fruit/Banana Fruit/Onion Bulb/Arctium Lappa Root/Spinach Leaf/ Orange Peel/Tomato Fruit/Phaseolus Radiatus Sprout/Pumpkin Fruit Extract Ferment Filtrate', NULL, NULL, NULL, 'This is a filtrate of the product obtained by the fermentation of Pyrus Malus (Apple) Fruit Extract, Daucus Carota Sativa (Carrot) Root Extract, Raphanus Sativus (Radish) Root Extract, Brassica Oleracea Capitata (Cabbage) Leaf Extract, the leaves of Apium graveolens (Celery), Cucumis Sativus (Cucumber) Fruit Extract, Musa Sapientum (Banana) Fruit Extract, Allium Cepa (Onion) Bulb Extract, Arctium Lappa Root Extract, Spinacia Oleracea (Spinach) Leaf Extract, Citrus Nobilis (Mandarin Orange) Peel Extract, Solanum Lycopersicum (Tomato) Fruit Extract, the bud of Phaseolus radiatus, and the fruit of Cucurbita moschata (Pumpkin) by the microorganisms, Saccharomyces and Leuconostoc. The accepted scientific name for Cucurbita moschate is Cucurbita moschata.', NULL, '-', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"6ce8add8-1bf6-4095-a3dd-e7926cbcfd5e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":5.3189683,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Saccharomyces/Leuconostoc/Apple Fruit/Carrot Root/Radish Root/Cabbage Leaf/Celery Leaf/Cucumber Fruit/Banana Fruit/Onion Bulb/Arctium Lappa Root/Spinach Leaf/ Orange Peel/Tomato Fruit/Phaseolus Radiatus Sprout/Pumpkin Fruit Extract Ferment Filtrate"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["This is a filtrate of the product obtained by the fermentation of Pyrus Malus (Apple) Fruit Extract, Daucus Carota Sativa (Carrot) Root Extract, Raphanus Sativus (Radish) Root Extract, Brassica Oleracea Capitata (Cabbage) Leaf Extract, the leaves of Apium graveolens (Celery), Cucumis Sativus (Cucumber) Fruit Extract, Musa Sapientum (Banana) Fruit Extract, Allium Cepa (Onion) Bulb Extract, Arctium Lappa Root Extract, Spinacia Oleracea (Spinach) Leaf Extract, Citrus Nobilis (Mandarin Orange) Peel Extract, Solanum Lycopersicum (Tomato) Fruit Extract, the bud of Phaseolus radiatus, and the fruit of Cucurbita moschata (Pumpkin) by the microorganisms, Saccharomyces and Leuconostoc. The accepted scientific name for Cucurbita moschate is Cucurbita moschata."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["6ce8add8-1bf6-4095-a3dd-e7926cbcfd5e"],"reference":["90336A8D8C612222C7FCA58062D06B53"],"cosmeticRestriction":[],"ecNo":["-"],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SACCHAROMYCES/LEUCONOSTOC/APPLE FRUIT/CARROT ROOT/RADISH ROOT/CABBAGE LEAF/CELERY LEAF/CUCUMBER FRUIT/BANANA FRUIT/ONION BULB/ARCTIUM LAPPA ROOT/SPINACH LEAF/ ORANGE PEEL/TOMATO FRUIT/PHASEOLUS RADIATUS SPROUT/PUMPKIN FRUIT EXTRACT FERMENT FILTRATE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":["-"],"substanceId":["85566"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - HUMECTANT"],"esDA_IngestDate":["2024-08-26T14:41:26.867+0200"],"currentVersion":["1"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2