  (86461, '5db41c5c-27e4-489c-906d-1b71ca7b4d3f'::uuid, 'PRUNUS DOMESTICA SEED POWDER', 'PRUNUS DOMESTICA SEED POWDER', NULL, NULL, NULL, 'Prunus Domestica Seed Powder is the powder obtained from the dried, ground seeds of Prunus domestica. The accepted scientific name for Prunus domestica is Prunus x domestica.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5db41c5c-27e4-489c-906d-1b71ca7b4d3f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.6951594,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["PRUNUS DOMESTICA SEED POWDER"],"otherRestrictions":["ban substances that deplete the ozone layer"],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Prunus Domestica Seed Powder is the powder obtained from the dried, ground seeds of Prunus domestica. The accepted scientific name for Prunus domestica is Prunus x domestica."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["6EEC7AAFC051962DE35EA85A192A89B9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["PRUNUS DOMESTICA SEED POWDER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["86461"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["EXFOLIATING"],"esDA_IngestDate":["2023-05-22T14:32:38.061+0200"],"currentVersion":["1"],"corporate-search-version":["