  (87482, '5d5849cf-ee3e-42af-8894-8dde9d9e7e2f'::uuid, 'SODIUM HYDROLYZED POTATO STARCH DODECENYLSUCCINATE', 'SODIUM HYDROLYZED POTATO STARCH DODECENYLSUCCINATE', NULL, NULL, NULL, 'Sodium Hydrolyzed Potato Starch Dodecenylsuccinate is the sodium salt of the product obtained by the reaction of Dextrin with dodecenylsuccinic anhydride.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5d5849cf-ee3e-42af-8894-8dde9d9e7e2f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9887555,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SODIUM HYDROLYZED POTATO STARCH DODECENYLSUCCINATE"],"otherRestrictions":["ban substances that deplete the ozone layer"],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Sodium Hydrolyzed Potato Starch Dodecenylsuccinate is the sodium salt of the product obtained by the reaction of Dextrin with dodecenylsuccinic anhydride."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["CC5BFA6F1B140F71227B81A90233FEA5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SODIUM HYDROLYZED POTATO STARCH DODECENYLSUCCINATE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["87482"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SURFACTANT - FOAM BOOSTING","SURFACTANT - CLEANSING"],"esDA_IngestDat