  (87483, 'b3334490-1b0f-4bea-8c55-294130a6eb10'::uuid, 'POLYALKYLAMINOESTER-1', 'POLYALKYLAMINOESTER-1', NULL, NULL, NULL, 'Polyalkylaminoester-1 is a complex polymer made first by polymerizing butadiene to form a pre-polymer of polybutadiene. The polybutadiene is capped on each end with one mol of propylene oxide to form a hydroxyl-terminated pre-polymer. One mol of acrylic acid is added to each end of the pre-polymer via esterification. Finally, the pre-polymers are linked together by a Michael addition reaction between the acrylate end groups and N,N-Bis(2-hydroxyethyl)-1,3-diaminopropane.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b3334490-1b0f-4bea-8c55-294130a6eb10","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.1155477,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYALKYLAMINOESTER-1"],"otherRestrictions":["ban substances that deplete the ozone layer"],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyalkylaminoester-1 is a complex polymer made first by polymerizing butadiene to form a pre-polymer of polybutadiene. The polybutadiene is capped on each end with one mol of propylene oxide to form a hydroxyl-terminated pre-polymer. One mol of acrylic acid is added to each end of the pre-polymer via esterification. Finally, the pre-polymers are linked together by a Michael addition reaction between the acrylate end groups and N,N-Bis(2-hydroxyethyl)-1,3-diaminopropane."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F695BF065C05EEBBDC8035ADF3E9D8F0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYALKYLAMINOESTER-1"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["87483"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR FIXING"],"esDA_IngestDate":["2023-05-22T15:03:17.389+0200"],"currentVersion":["1"],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T15:03:17.370+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"b3334490-1b0f-4bea-8c55-294130a6eb10. Available at: urn:test"}'::jsonb),
