  (88122, 'ff0baa79-655e-44bb-a71c-a8666f6a48a8'::uuid, 'RH-POLYPEPTIDE-51', 'RH-POLYPEPTIDE-51', NULL, NULL, NULL, 'rh-Polypeptide-51 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is directly isolated from a human cell which codes for Extracellular Superoxide Dismutase [Cu-Zn] used as such or adapted to the production host. It contains a maximum of 240 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ff0baa79-655e-44bb-a71c-a8666f6a48a8","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RH-POLYPEPTIDE-51"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["rh-Polypeptide-51 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is directly isolated from a human cell which codes for Extracellular Superoxide Dismutase [Cu-Zn] used as such or adapted to the production host. It contains a maximum of 240 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["E28A7A3477549218EC5C569874DACC35"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentr