  (88139, '7d023d33-64bd-46ad-a976-aa79fb0666cd'::uuid, 'SH-POLYPEPTIDE-50', 'SH-POLYPEPTIDE-50', NULL, NULL, NULL, 'sh-Polypeptide-50 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is synthesized to be identical to the human gene which codes for Tropoelastin used such or adapted to the production host. It contains a maximum of 786 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"7d023d33-64bd-46ad-a976-aa79fb0666cd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-50"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-50 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is synthesized to be identical to the human gene which codes for Tropoelastin used such or adapted to the production host. It contains a maximum of 786 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["E08CE91A00CC3AB2789ECB0DE3503C41"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublicat