  (88306, 'c283aba8-e10a-43d5-93b1-29fef8283d4e'::uuid, 'SH-POLYPEPTIDE-53', 'SH-POLYPEPTIDE-53', NULL, NULL, NULL, 'sh-Polypeptide-53 is a single chain synthetic human peptide, produced by fermentation in Trichoplusia ni. The starting gene is a synthesized copy of the human gene which codes for Insulin-Like Growth Factor Binding Protein 6 used as such or adapted to the production host. It contains a maximum of 240 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, '-', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"c283aba8-e10a-43d5-93b1-29fef8283d4e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-53"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-53 is a single chain synthetic human peptide, produced by fermentation in Trichoplusia ni. The starting gene is a synthesized copy of the human gene which codes for Insulin-Like Growth Factor Binding Protein 6 used as such or adapted to the production host. It contains a maximum of 240 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["155BAA2FA75DCAE5C567E330A58143F7"],"cosmeticRestriction":[],"ecNo":["-"],"maxim