  (88536, '9b7bfa3d-405a-44e9-8f84-e74df3486e05'::uuid, 'SH-POLYPEPTIDE-56 TRIPEPTIDE-44 SH-OLIGOPEPTIDE-1', 'SH-POLYPEPTIDE-56 TRIPEPTIDE-44 SH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'sh-Polypeptide-56 Tripeptide-44 sh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-56, sh-Oligopeptide-1 and Tripeptide-44. The fused peptide contains 1060 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, '-', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9b7bfa3d-405a-44e9-8f84-e74df3486e05","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-56 TRIPEPTIDE-44 SH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-56 Tripeptide-44 sh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-56, sh-Oligopeptide-1 and Tripeptide-44. The fused peptide contains 1060 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B2E59AD8C8366EE5B3417052CF77775C"],"cosmeticRestriction":[],"ecNo":["-"],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublicat