  (89445, '4ca8ca5d-73bc-45fe-ba4c-2e67e8d9945e'::uuid, 'SH-POLYPEPTIDE-1', 'SH-POLYPEPTIDE-1', NULL, NULL, NULL, 'sh-Polypeptide-1 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Basic Fibroblast Growth Factor used as such or adapted to the production host. It contains a maximum of 288 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4ca8ca5d-73bc-45fe-ba4c-2e67e8d9945e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-1 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Basic Fibroblast Growth Factor used as such or adapted to the production host. It contains a maximum of 288 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["DBD5F523DB9B7C0A435C1AE34E954843"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"offi