  (89601, 'ab14ae22-7710-461e-85d2-77a70138032f'::uuid, 'TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 SH-POLYPEPTIDE-60', 'TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 SH-POLYPEPTIDE-60', NULL, NULL, NULL, 'Tripeptide-46 Hexapeptide-40 Decapeptide-27 Oligopeptide-91 sh-Polypeptide-60 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Tripeptide-46, Hexapeptide-40, Decapeptide-27, Oligopeptide-91, and sh-Polypeptide-6. The fused peptide contains 228 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ab14ae22-7710-461e-85d2-77a70138032f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 SH-POLYPEPTIDE-60"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tripeptide-46 Hexapeptide-40 Decapeptide-27 Oligopeptide-91 sh-Polypeptide-60 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Tripeptide-46, Hexapeptide-40, Decapeptide-27, Oligopeptide-91, and sh-Polypeptide-6. The fused peptide contains 228 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["54FF4C915E50E2AB8C9B395CA049F0E9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 SH-POLYPEPTIDE-60"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["89601"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING","SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:34:49.532+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:34:49.506+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"ab14ae22-7710-461e-85d2-77a70138032f. Available at: urn:test"}'::jsonb),
  (89606, '75f249a8-c000-4250-94b8-f504f832cf92'::uuid, 'SH-POLYPEPTIDE-60', 'SH-POLYPEPTIDE-60', NULL, NULL, NULL, 'sh-Polypeptide-60 is a single chain synthetic human peptide, produced by fermentation in E.Coli. The starting gene is a synthesized copy of the human gene which codes for Superoxide Dismutase 1 used as such or adapted to the production host. It contains a maximum of 154 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"75f249a8-c000-4250-94b8-f504f832cf92","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-60"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-60 is a single chain synthetic human peptide, produced by fermentation in E.Coli. The starting gene is a synthesized copy of the human gene which codes for Superoxide Dismutase 1 used as such or adapted to the production host. It contains a maximum of 154 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["C4B120B0DD61DF641369F9CE330485F0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJourna