  (89778, '4f35c25f-ad69-40d7-861e-e02e5b07cfa3'::uuid, 'SH-POLYPEPTIDE-8', 'SH-POLYPEPTIDE-8', NULL, NULL, NULL, 'sh-Polypeptide-8 is a single chain synthetic human peptide, produced by fermentation in E.Coli. The starting gene is a synthesized copy of the human gene which codes for Platelet Derived Growth Factor used as such or adapted to the production host. It contains a maximum of 211 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4f35c25f-ad69-40d7-861e-e02e5b07cfa3","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-8"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-8 is a single chain synthetic human peptide, produced by fermentation in E.Coli. The starting gene is a synthesized copy of the human gene which codes for Platelet Derived Growth Factor used as such or adapted to the production host. It contains a maximum of 211 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EECAE59FC4DB97D722F25AE44EFDA875"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"off