  (90081, 'f66c2513-a53b-45ff-9c61-1c901c2db83f'::uuid, 'RH-POLYPEPTIDE-33', 'RH-POLYPEPTIDE-33', NULL, NULL, NULL, 'rh-Polypeptide-33 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is directly isolated from a human cell which codes for Tumor Necrosis Factor Alpha used as such or adapted to the production host. It contains a maximum of 233 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f66c2513-a53b-45ff-9c61-1c901c2db83f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RH-POLYPEPTIDE-33"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["rh-Polypeptide-33 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is directly isolated from a human cell which codes for Tumor Necrosis Factor Alpha used as such or adapted to the production host. It contains a maximum of 233 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["7608F1DFF2DF13F20C8675822ACB97AF"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngr