  (90085, '8a3e00c4-4eff-4c6f-9b37-87bc630a5cfb'::uuid, 'SH-POLYPEPTIDE-56 RH-POLYPEPTIDE-65', 'SH-POLYPEPTIDE-56 RH-POLYPEPTIDE-65', NULL, NULL, NULL, 'sh-Polypeptide-56 rh-Polypeptide-65 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-56 and rh-Polypeptide-65 . The fused peptide contains 1104 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8a3e00c4-4eff-4c6f-9b37-87bc630a5cfb","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-56 RH-POLYPEPTIDE-65"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-56 rh-Polypeptide-65 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-56 and rh-Polypeptide-65 . The fused peptide contains 1104 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["A816348CF9B869A41369B7068A8A4081"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-POLYPEPTIDE-56 RH-POLYPEPTIDE-65"],"esST_FileName":["file.t