  (90430, '8d735d0f-95b7-4ef6-868d-700236b291fe'::uuid, 'R-LEUCOSPORIDIUM POLYPEPTIDE-1', 'R-LEUCOSPORIDIUM POLYPEPTIDE-1', NULL, NULL, NULL, 'r-Leucosporidium Polypeptide-1 is a single chain recombinant protein produced by fermentation in Pichia pastoris. The starting gene is directly isolated from Leucosporidium which codes for Antifreeze Protein. The protein contains a maximum of 261 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8d735d0f-95b7-4ef6-868d-700236b291fe","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-LEUCOSPORIDIUM POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-Leucosporidium Polypeptide-1 is a single chain recombinant protein produced by fermentation in Pichia pastoris. The starting gene is directly isolated from Leucosporidium which codes for Antifreeze Protein. The protein contains a maximum of 261 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4B6C29F34BEEF9776E37D06FE5876CCB"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-LEUCOSPORIDIUM POLYPEPTIDE-1"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["90430"],"annexNo