  (90638, 'b77e600b-f674-4198-8e67-bbba2464d4d0'::uuid, 'METHIONYL R-SALMON OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-2', 'METHIONYL R-SALMON OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-2', NULL, NULL, NULL, 'Methionyl r-Salmon Oligopeptide-1 sh-Oligopeptide-2 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Salmon Oligopeptide-1 and sh-Oligopeptide-2 with the code for methionine. The fused peptide contains 85 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b77e600b-f674-4198-8e67-bbba2464d4d0","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL R-SALMON OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-2"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl r-Salmon Oligopeptide-1 sh-Oligopeptide-2 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Salmon Oligopeptide-1 and sh-Oligopeptide-2 with the code for methionine. The fused peptide contains 85 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["AE2948B21F79327999F995ED2FAE8C03"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[]