  (90651, '6aab694c-b248-4d82-abc6-414f5162f375'::uuid, 'R-SALMON OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1', 'R-SALMON OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'r-Salmon Oligopeptide-1 sh-Oligopeptide-1 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Salmon Oligopeptide-1, and sh-Oligopeptide-1. The fused peptide contains 63 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"6aab694c-b248-4d82-abc6-414f5162f375","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-SALMON OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-Salmon Oligopeptide-1 sh-Oligopeptide-1 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Salmon Oligopeptide-1, and sh-Oligopeptide-1. The fused peptide contains 63 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["3E11277F84EC1DC0DCCD70D6CFD4EC7C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-SALMON OLIGOPEPTIDE-1 SH-OLIG