  (90655, '9ea07d68-55fd-416e-aa8d-e762e144d155'::uuid, 'SH-POLYPEPTIDE-16', 'SH-POLYPEPTIDE-16', NULL, NULL, 'PGF,PLGF', 'sh-Polypeptide-16 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is synthesized to be identical to the human gene which codes for Placental Growth Factor used such or adapted to the production host. It contains a maximum of 221 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9ea07d68-55fd-416e-aa8d-e762e144d155","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-16"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["PGF,PLGF"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-16 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is synthesized to be identical to the human gene which codes for Placental Growth Factor used such or adapted to the production host. It contains a maximum of 221 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["6F86BA0F07A239BC0318CA425C4BD29D"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifi