  (90674, 'addd5a7e-3519-44dd-b9f5-49f060fa3d92'::uuid, 'OLIGOPEPTIDE-91 RH-OLIGOPEPTIDE-1', 'OLIGOPEPTIDE-91 RH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'Oligopeptide-91 rh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Oligopeptide-1 and Oligopeptide-91. The fused peptide contains 74 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"addd5a7e-3519-44dd-b9f5-49f060fa3d92","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["OLIGOPEPTIDE-91 RH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Oligopeptide-91 rh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Oligopeptide-1 and Oligopeptide-91. The fused peptide contains 74 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["FA923BFA148EE4269941F4B12F4F4B7C"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["OLIGOPEPTIDE-91 RH-OLIGOPEPTIDE-1"],"esST_FileName":["file.txt"],"casNo":[],"subs