  (90790, '7f253242-72a7-4214-af40-ab44fd2b8ff4'::uuid, 'SH-OLIGOPEPTIDE-75 AMIDE', 'SH-OLIGOPEPTIDE-75 AMIDE', NULL, NULL, NULL, 'sh-Oligopeptide-75 Amide is a 14 amino acid protein fragment in which the C-terminus of the peptide is an amide, and it is produced synthetically to be identical to a fragment of the human protein, Sperm Protamine P1. The protein contains a maximum of 51 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"7f253242-72a7-4214-af40-ab44fd2b8ff4","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OLIGOPEPTIDE-75 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-75 Amide is a 14 amino acid protein fragment in which the C-terminus of the peptide is an amide, and it is produced synthetically to be identical to a fragment of the human protein, Sperm Protamine P1. The protein contains a maximum of 51 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["C8E75C48A4FA101CDC7C6666D72B1956"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-OLIGOPEPTIDE-75 AMIDE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["90790"],"annexNo":[],"p