  (90883, '7fddd088-05d7-4b2b-821c-4ad9bc90c2ab'::uuid, 'SH-POLYPEPTIDE-51', 'SH-POLYPEPTIDE-51', NULL, NULL, NULL, 'sh-Polypeptide-51 is a single chain synthetic human peptide, produced by fermentation in E.Coli. The starting gene is a synthesized copy of the human gene which codes for Superoxide Dismutase used as such or adapted to the production host. It contains a maximum of 240 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"7fddd088-05d7-4b2b-821c-4ad9bc90c2ab","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-51"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-51 is a single chain synthetic human peptide, produced by fermentation in E.Coli. The starting gene is a synthesized copy of the human gene which codes for Superoxide Dismutase used as such or adapted to the production host. It contains a maximum of 240 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["992E01BA6CDBA8224BCA8F496A94535F"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPub