  (90910, 'ee56658f-e718-48d6-9b70-c5269a496f7f'::uuid, 'OLIGOPEPTIDE-107 SH-OLIGOPEPTIDE-1', 'OLIGOPEPTIDE-107 SH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'Oligopeptide-107 sh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-1 and Oligopeptide-107. The fused peptide contains 67 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ee56658f-e718-48d6-9b70-c5269a496f7f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["OLIGOPEPTIDE-107 SH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Oligopeptide-107 sh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-1 and Oligopeptide-107. The fused peptide contains 67 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["BEA73960DACE5A6C508487F2E4FAA8B0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["OLIGOPEPTIDE-107 SH-OLIGOPEPTIDE-1"],"esST_FileName":["file.txt"],"casNo":[],"substanc