  (90911, '631642f7-0a2c-4a97-bc3e-e7cee78a58cf'::uuid, 'ENDONUCLEASE V', 'ENDONUCLEASE V', NULL, NULL, 'Den V', 'Endonuclease V is the recombinant protein produced by fermentation in E. coli. The starting gene is isolated from Enterobacteria Phage T4 and codes for Endonuclease V. The protein contains a maximum of 138 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"631642f7-0a2c-4a97-bc3e-e7cee78a58cf","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ENDONUCLEASE V"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Den V"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Endonuclease V is the recombinant protein produced by fermentation in E. coli. The starting gene is isolated from Enterobacteria Phage T4 and codes for Endonuclease V. The protein contains a maximum of 138 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4ECF920CA7247E73BA93E15C9ACFD42B"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ENDONUCLEASE V"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["90911"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],