  (90972, 'a0a7bf48-8313-4c6a-8366-07e27cce6c78'::uuid, 'TRIPEPTIDE-49 OLIGOPEPTIDE-91 DIPEPTIDE-19 R-BOVINE OCTAPEPTIDE-1', 'TRIPEPTIDE-49 OLIGOPEPTIDE-91 DIPEPTIDE-19 R-BOVINE OCTAPEPTIDE-1', NULL, NULL, NULL, 'Tripeptide-49 Oligopeptide-91 Dipeptide-19 r-Bovine Octapeptide-1 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Bovine Octapeptide-1, Tripeptide-49, Oligopeptide-91 and Dipeptide-19. The fused peptide contains 34 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a0a7bf48-8313-4c6a-8366-07e27cce6c78","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIPEPTIDE-49 OLIGOPEPTIDE-91 DIPEPTIDE-19 R-BOVINE OCTAPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tripeptide-49 Oligopeptide-91 Dipeptide-19 r-Bovine Octapeptide-1 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Bovine Octapeptide-1, Tripeptide-49, Oligopeptide-91 and Dipeptide-19. The fused peptide contains 34 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["A60AAB5081213C33658A63AF5979C36