  (91114, 'b5a7a1f1-d7c6-42f6-b7a4-ede1521f789a'::uuid, 'ACRYLOYL DIMETHYL TAURATE/MELAMINE/PEG-6 METHACRYLATE CROSSPOLYMER', 'ACRYLOYL DIMETHYL TAURATE/MELAMINE/PEG-6 METHACRYLATE CROSSPOLYMER', NULL, NULL, NULL, 'Acryloyl Dimethyl Taurate/Melamine/PEG-6 Methacrylate Crosspolymer is a complex, crosslinked polymer that is made by reacting melamine with Glutaral followed by the reaction with 2-Acrylamido-2-Methylpropane Sulfonic Acid and PEG-6 methacrylate. The resulting polymer is then further reacted with more melamine.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b5a7a1f1-d7c6-42f6-b7a4-ede1521f789a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ACRYLOYL DIMETHYL TAURATE/MELAMINE/PEG-6 METHACRYLATE CROSSPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Acryloyl Dimethyl Taurate/Melamine/PEG-6 Methacrylate Crosspolymer is a complex, crosslinked polymer that is made by reacting melamine with Glutaral followed by the reaction with 2-Acrylamido-2-Methylpropane Sulfonic Acid and PEG-6 methacrylate. The resulting polymer is then further reacted with more melamine."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B4791E40ACADA46416D928C671459AF5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ACRYLOYL DIMETHYL TAURATE/MEL