  (91451, '2e706722-6366-46dc-bb8a-fc470b23f50a'::uuid, 'METHIONYL SH-OLIGOPEPTIDE-75 SH-POLYPEPTIDE-8', 'METHIONYL SH-OLIGOPEPTIDE-75 SH-POLYPEPTIDE-8', NULL, NULL, NULL, 'Methionyl sh-Oligopeptide-75 sh-Polypeptide-8 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-75 (q.v.) and sh-Polypeptide-8 (q.v.) with the initiation code for methionine. The fusion peptide contains 225 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2e706722-6366-46dc-bb8a-fc470b23f50a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL SH-OLIGOPEPTIDE-75 SH-POLYPEPTIDE-8"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl sh-Oligopeptide-75 sh-Polypeptide-8 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-75 (q.v.) and sh-Polypeptide-8 (q.v.) with the initiation code for methionine. The fusion peptide contains 225 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B7CA9B5B7FC0852D3E3D3D73D2E04A66"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["METHIONYL SH-OLIGOPEPTIDE-75 SH-POLYPEPTIDE-8"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["91451"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:37:36.532+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:37:36.499+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"2e706722-6366-46dc-bb8a-fc470b23f50a. Available at: urn:test"}'::jsonb),
  (91452, 'a071a011-8988-43e2-a762-cf24657a022a'::uuid, 'METHIONYL SH-OLIGOPEPTIDE-75 SH-OLIGOPEPTIDE-2', 'METHIONYL SH-OLIGOPEPTIDE-75 SH-OLIGOPEPTIDE-2', NULL, NULL, NULL, 'Methionyl sh-Oligopeptide-75 sh-Oligopeptide-2 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-75 and sh-Oligopeptide-2 with the code for methionine. The fused peptide contains 85 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a071a011-8988-43e2-a762-cf24657a022a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL SH-OLIGOPEPTIDE-75 SH-OLIGOPEPTIDE-2"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl sh-Oligopeptide-75 sh-Oligopeptide-2 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-75 and sh-Oligopeptide-2 with the code for methionine. The fused peptide contains 85 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4691638501A261860BE08263C3DCB5ED"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJou