  (91470, '8247d502-cfe6-44c2-b964-7fd63895ab51'::uuid, 'SH-POLYPEPTIDE-78', 'SH-POLYPEPTIDE-78', NULL, NULL, 'HSP 86', 'sh-Polypeptide-78 is a single chain synthetic human peptide, produced by fermentation in E. Coli. The starting gene is a synthesized copy of the human gene which codes for Heat Shock Protein 90-Alpha used as such or adapted to the production host. It contains a maximum of 732 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8247d502-cfe6-44c2-b964-7fd63895ab51","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-78"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["HSP 86"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-78 is a single chain synthetic human peptide, produced by fermentation in E. Coli. The starting gene is a synthesized copy of the human gene which codes for Heat Shock Protein 90-Alpha used as such or adapted to the production host. It contains a maximum of 732 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["7D84A51A0D524C7AB23CD61B202E14F9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngred