  (91598, '9d954057-6a31-4d22-8933-285dbc1b7efd'::uuid, 'SH-POLYPEPTIDE-64', 'SH-POLYPEPTIDE-64', NULL, NULL, 'AQP-1', 'sh-Polypeptide-64 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Aquaporin-1 used as such or adapted to the production host. It contains a maximum of 269 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9d954057-6a31-4d22-8933-285dbc1b7efd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-64"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["AQP-1"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-64 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Aquaporin-1 used as such or adapted to the production host. It contains a maximum of 269 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["74174BC34A29F1861653EA5451DE2191"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublicati