  (91652, '257f5e8d-b001-4c40-b9ac-43e2814f49ee'::uuid, 'TRIPEPTIDE-49 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-1', 'TRIPEPTIDE-49 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-1', NULL, NULL, NULL, 'Tripeptide-49 Oligopeptide-91 Dipeptide-19 sh-Polypeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-1, Tripeptide-49, Oligopeptide-91, and Dipeptide-19. The fused peptide contains 314 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"257f5e8d-b001-4c40-b9ac-43e2814f49ee","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIPEPTIDE-49 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tripeptide-49 Oligopeptide-91 Dipeptide-19 sh-Polypeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-1, Tripeptide-49, Oligopeptide-91, and Dipeptide-19. The fused peptide contains 314 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["A2745B01482FB478CE4A5FCABB920635"],"cosmeticRestriction":[],"ecNo":[],"ma