  (91771, '40124005-351a-40dd-b229-5f585dde884c'::uuid, 'TETRAPEPTIDE-38 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-80', 'TETRAPEPTIDE-38 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-80', NULL, NULL, NULL, 'Tetrapeptide-38 Hexapeptide-40 Decapeptide-27 Oligopeptide-91 Dipeptide-19 sh-Polypeptide-80 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Tetrapeptide-38, Hexapeptide-40, Decapeptide-27, Oligopeptide-91, Dipeptide-19, and sh-Polypeptide-80. The fused peptide contains 241 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"40124005-351a-40dd-b229-5f585dde884c","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TETRAPEPTIDE-38 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-80"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tetrapeptide-38 Hexapeptide-40 Decapeptide-27 Oligopeptide-91 Dipeptide-19 sh-Polypeptide-80 is a single chain synthetic fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Tetrapeptide-38, Hexapeptide-40, Decapeptide-27, Oligopeptide-91, Dipeptide-19, and sh-Polypeptide-80. The fused peptide contains 241 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["ED6263059BA048739155E3774386F776"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TETRAPEPTIDE-38 HEXAPEPTIDE-40 DECAPEPTIDE-27 OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-80"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["91771"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:39:37.234+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:39:37.213+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"40124005-351a-40dd-b229-5f585dde884c. Available at: urn:test"}'::jsonb),
