  (91835, '32fda4ba-0c63-4234-b5f4-8b5cbab73f7e'::uuid, 'SODIUM POLYACRYLATE CROSSPOLYMER-1', 'SODIUM POLYACRYLATE CROSSPOLYMER-1', NULL, NULL, NULL, 'Sodium Polyacrylate Crosspolymer-1 is a complex crosslinked polymer that is made by first preparing a silicone copolymer by reacting a methacrylate-terminated polydimethylsiloxane polymer containing silicon hydride groups with PEG-18/PPG-17 allyl ether. The silicone copolymer is then dispersed in water that contains sodium hydroxide and reacted with Methacrylic Acid and methacryloyl PPG-6 phosphate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"32fda4ba-0c63-4234-b5f4-8b5cbab73f7e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SODIUM POLYACRYLATE CROSSPOLYMER-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Sodium Polyacrylate Crosspolymer-1 is a complex crosslinked polymer that is made by first preparing a silicone copolymer by reacting a methacrylate-terminated polydimethylsiloxane polymer containing silicon hydride groups with PEG-18/PPG-17 allyl ether. The silicone copolymer is then dispersed in water that contains sodium hydroxide and reacted with Methacrylic Acid and methacryloyl PPG-6 phosphate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EC10860CF3CC3C83C0138200B5CE5BA5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIng