  (91971, '30087d29-37f8-470b-8e98-c71eea038cbd'::uuid, 'SH-OLIGOPEPTIDE-78', 'SH-OLIGOPEPTIDE-78', NULL, NULL, NULL, 'sh-Oligopeptide-78 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which appears in multiple Type II Keratin proteins. It contains a maximum of 123 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"30087d29-37f8-470b-8e98-c71eea038cbd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OLIGOPEPTIDE-78"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-78 is a single chain synthetic human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which appears in multiple Type II Keratin proteins. It contains a maximum of 123 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["CEBDE93EA1E0C90C5B57321B9D9030C5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-OLIGOPEPTIDE-78"],"esST_File