  (92133, '5831c0d2-894e-4d9e-96fa-7217b3638b2f'::uuid, 'OCTAPEPTIDE-22 R-THERMUS THERMOPHILUS PUTATIVE ESTERASE HEXAPEPTIDE-40', 'OCTAPEPTIDE-22 R-THERMUS THERMOPHILUS PUTATIVE ESTERASE HEXAPEPTIDE-40', NULL, NULL, NULL, 'Octapeptide-22 r-Thermus Thermophilus Putative Esterase Hexapeptide-40 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene that codes for Thermus Thermophilus Putative Esterase, Octapeptide-22, and Hexapeptide-40. The fused peptide contains 329 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5831c0d2-894e-4d9e-96fa-7217b3638b2f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["OCTAPEPTIDE-22 R-THERMUS THERMOPHILUS PUTATIVE ESTERASE HEXAPEPTIDE-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Octapeptide-22 r-Thermus Thermophilus Putative Esterase Hexapeptide-40 is a single chain recombinant fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene that codes for Thermus Thermophilus Putative Esterase, Octapeptide-22, and Hexapeptide-40. The fused peptide contains 329 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B785