  (92227, 'b10f6683-f12f-474f-b6c3-0c8d01283ac1'::uuid, 'CERAMIDE NG', 'CERAMIDE NG', NULL, NULL, 'Ceramide 2', 'Ceramide NG, formerly known under the INCI Name Ceramide 2, is the N-acylated sphingolipid consisting of Sphinganine having the D-erythro structure linked to a normal saturated or unsaturated fatty acid. As opposed to the broader definition for Ceramide 2 which includes sphingolipids consisting of either sphingosine or dihydrosphingosine (sphinganine), Ceramide NG is limited to sphinganine-based ceramides', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b10f6683-f12f-474f-b6c3-0c8d01283ac1","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["CERAMIDE NG"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Ceramide 2"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Ceramide NG, formerly known under the INCI Name Ceramide 2, is the N-acylated sphingolipid consisting of Sphinganine having the D-erythro structure linked to a normal saturated or unsaturated fatty acid. As opposed to the broader definition for Ceramide 2 which includes sphingolipids consisting of either sphingosine or dihydrosphingosine (sphinganine), Ceramide NG is limited to sphinganine-based ceramides"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["DE2619E0BA2623356C2E437F2103F065"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublicatio