  (92350, '3f01dd2a-aaa0-4cdb-87f7-447b4f0bef8d'::uuid, 'CHLOROPHYLLIN-COPPER COMPLEX', 'CHLOROPHYLLIN-COPPER COMPLEX', NULL, NULL, 'Chlorophyl Cu Complex,Chlorophyllin, Copper Sodium Complex,CI 75810,Copper Sodium Chlorophyllin,Natural Green 3,Potassium Sodium Copper Chlorophyllin,Sodium Copper Chlorophyllin', 'Chlorophyllin-Copper Complex is obtained from chlorophyll by replacing the methyl and phytyl ester groups with alkali and replacing the magnesium with copper.  To identify the colorant meeting the requirements for labeling purposes in the US, the INCI Name Chlorophyllin-Copper Complex must be used.  To identify the colorant allowed for use in the European Union (EU), the INCI Name CI 75810 must be used.', NULL, '234-242-5', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"3f01dd2a-aaa0-4cdb-87f7-447b4f0bef8d","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["CHLOROPHYLLIN-COPPER COMPLEX"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Chlorophyl Cu Complex,Chlorophyllin, Copper Sodium Complex,CI 75810,Copper Sodium Chlorophyllin,Natural Green 3,Potassium Sodium Copper Chlorophyllin,Sodium Copper Chlorophyllin"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Chlorophyllin-Copper Complex is obtained from chlorophyll by replacing the methyl and phytyl ester groups with alkali and replacing the magnesium with copper.  To identify the colorant meeting the requirements for labeling purposes in the US, the INCI Name Chlorophyllin-Copper Complex must be used.  To identify the colorant allowed for use in the European Union (EU), the INCI Name CI 75810 must be used."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["420C414AF82F3950D02A0770D586820B"],"cosmeticRestriction":[],"ecNo":["234-242-5"],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["CHLOROPHYLLIN-COPPER COMPLEX"],"esST_FileName":["file.txt"],"casNo":["11006-34-1"],"substanceId":["92350"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","COLORANT","DEODORANT"],"esDA_IngestDate":["2023-05-22T16:49:11.663+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:49:11.636+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"3f01dd2a-aaa0-4cdb-87f7-447b4f0bef8d. Available at: urn:test"}'::jsonb),
