  (92958, '2f114410-10ba-4565-9ec4-113589a637a1'::uuid, 'R-CLOSTRIDIUM HISTOLYTICUM COLLAGENASE H', 'R-CLOSTRIDIUM HISTOLYTICUM COLLAGENASE H', NULL, NULL, 'ColH', 'r-Clostridium Histolyticum Collagenase H is a single chain recombinant  Clostridium histolyticum  protein, with one mutation, produced by fermentation in  E. coli.  The starting gene is directly isolated from  Clostridium histolyticum  which codes for the enzyme collagenase.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2f114410-10ba-4565-9ec4-113589a637a1","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-CLOSTRIDIUM HISTOLYTICUM COLLAGENASE H"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["ColH"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-Clostridium Histolyticum Collagenase H is a single chain recombinant  Clostridium histolyticum  protein, with one mutation, produced by fermentation in  E. coli.  The starting gene is directly isolated from  Clostridium histolyticum  which codes for the enzyme collagenase."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["13206CDA1B4F222E766B380736410F32"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-CLOSTRIDIUM HISTOLYTICUM COLLAGENASE H"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["92958"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_Con