nciName":["DIISOPROPANOLAMINE/METHYLHEXAHYDROPHTHALIC ANHYDRIDE ETHYLHEXANOATE COPOLYMER"],"esST_FileName":["file.txt"],"casNo":["1590416-18-4"],"substanceId":["93225"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["FILM FORMING"],"esDA_IngestDate":["2023-05-22T16:41:34.406+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:41:34.385+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"121f0117-3776-4878-aa81-db7b794faa47. Available at: urn:test"}'::jsonb),
  (93226, '02b36efe-3375-4e8a-8b87-9acf5f194586'::uuid, 'METHACRYLOYLOXYPROPYL POLYSILSESQUIOXANE', 'METHACRYLOYLOXYPROPYL POLYSILSESQUIOXANE', NULL, NULL, '2-Propenoic acid, 2-methyl-, 3-(trimethoxysilyl)propyl ester, hydrolyzed', 'Methacryloyloxypropyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the methacryloxypropyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Methacryloyloxypropyl Polysilsesquioxane is prepared by the hydrolysis and condensation of Methacryloyl Propyltrimethoxysilane', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"02b36efe-3375-4e8a-8b87-9acf5f194586","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.583256,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHACRYLOYLOXYPROPYL POLYSILSESQUIOXANE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["2-Propenoic acid, 2-methyl-, 3-(trimethoxysilyl)propyl ester, hydrolyzed"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methacryloyloxypropyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the methacryloxypropyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Methacryloyloxypropyl Polysilsesquioxane is prepared by the hydrolysis and condensation of Methacryloyl Propyltrimethoxysilane"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["11EF6F0C5B606F7DD965EA5120106130"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["METHACRYLOYLOXYPROPYL POLYSILSESQUIOXANE"],"esST_FileName":["file.txt"],"casNo":["160185-24-0"],"substanceId":["93226"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ABRASIVE"],"esDA_IngestDate":["2023-05-22T16:43:24.553+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:43:24.526+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"02b36efe-3375-4e8a-8b87-9acf5f194586. Available at: urn:test"}'::jsonb),
  (93227, '60d500d2-bc09-4db4-9766-b490e7343548'::uuid, '3-HYDROXYBUTYRATE/4-HYDROXYBUTYRATE COPOLYMER', '3-HYDROXYBUTYRATE/4-HYDROXYBUTYRATE COPOLYMER', NULL, NULL, 'Butanoic acid, 3-hydroxy-, (3R)-, polymer with 4-hydroxybutanoic acid', '3-Hydroxybutyrate/4-Hydroxybutyrate Copolymer is a polymer of 3-hydroxybutyrate and 4-hydroxybutyrate produced through the fermentation of Glucose and 1,4-Butanediol by the microorganism,  E. coli.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"60d500d2-bc09-4db4-9766-b490e7343548","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.583256,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["3-HYDROXYBUTYRATE/4-HYDROXYBUTYRATE COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Butanoic acid, 3-hydroxy-, (3R)-, polymer with 4-hydroxybutanoic acid"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["3-Hydroxybutyrate/4-Hydroxybutyrate Copolymer is a polymer of 3-hydroxybutyrate and 4-hydroxybutyrate produced through the fermentation of Glucose and 1,4-Butanediol by the microorganism,  E. coli."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["948B11FCB9667CEBE584857D745082B2"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["3-HYDROXYBUTYRATE/4-HYDROXYBUTYRATE COPOLYMER"],"esST_FileName":["file.txt"],"casNo":["125495-90-1"],"substanceId":["93227"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"