  (93229, 'be9ec9b8-0f05-461e-85fb-ade5923db17a'::uuid, 'TRIMETHYLPENTYL POLYSILSESQUIOXANE', 'TRIMETHYLPENTYL POLYSILSESQUIOXANE', NULL, NULL, NULL, 'Trimethylpentyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the trimethylpentyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Trimethylpentyl Polysilsesquioxane is prepared by the hydrolysis and condensation of 2,4,4-trimethylpentyl trimethoxysilane', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"be9ec9b8-0f05-461e-85fb-ade5923db17a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.2819624,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIMETHYLPENTYL POLYSILSESQUIOXANE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Trimethylpentyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the trimethylpentyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Trimethylpentyl Polysilsesquioxane is prepared by the hydrolysis and condensation of 2,4,4-trimethylpentyl trimethoxysilane"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8AA285A8B2C7E5666882E526000ADE9C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TRIMETHYLPENTYL POLYSILSESQUIOXANE"],"esST_FileName":["file.txt"],"casNo":["190732-67-3,444619-08-3"],"substanceId":["93229"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["NAIL CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:43:24.986+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:43:24.961+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"be9ec9b8-0f05-461e-85fb-ade5923db17a. Available at: urn:test"}'::jsonb),
  (93230, 'a1643e8c-b81c-428b-85bd-e0aee2f19d55'::uuid, 'ISOBUTYL POLYSILSESQUIOXANE', 'ISOBUTYL POLYSILSESQUIOXANE', NULL, NULL, 'Pentacyclo[9.5.1.13,9.15,15.17,13]octasiloxane, 1,3,5,7,9,11,13,15-octakis(2-methylpropyl)-', 'Isobutyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the isobutyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Isobutyl Polysilsesquioxane is prepared by the hydrolysis and condensation of 2-methylpropyl trimethoxysilane.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a1643e8c-b81c-428b-85bd-e0aee2f19d55","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.2819624,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ISOBUTYL POLYSILSESQUIOXANE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Pentacyclo[9.5.1.13,9.15,15.17,13]octasiloxane, 1,3,5,7,9,11,13,15-octakis(2-methylpropyl)-"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Isobutyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the isobutyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Isobutyl Polysilsesquioxane is prepared by the hydrolysis and condensation of 2-methylpropyl trimethoxysilane."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["AF34C39F7A3CA758566F5C10C16CB666"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ISOBUTYL POLYSILSESQUIOXANE"],"esST_FileName":["file.txt"],"casNo":["221326-46-1"],"substanceId":["93230"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["NAIL CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:43:25.175+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:43:25.155+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"a1643e8c-b81c-428b-85bd-e0aee2f19d55. Available at: urn:test"}'::jsonb),
