  (93238, '7bdb45a0-eabc-4cd4-be43-6df7738a081f'::uuid, 'SILICONE QUATERNIUM-27', 'SILICONE QUATERNIUM-27', NULL, NULL, NULL, 'Silicone Quaternium-27 is a complex silicone polymer that is made in several steps. First, Glycidoxy Dimethicone is reacted with dimethylamine. The resulting siloxane polymer is then quaternized by reacting the tertiary amine groups created in the previous step with a glycidoxy-terminated polypropylene glycol that contains an average of seven mols of polypropylene oxide. Finally, additional quaternary ammonium groups are created on the silicone polymer by reacting epoxy groups left over from the previous step with dodecyldimethyl amine. The last two reactions are done in the presence of acetic acid so that the positive charges on the finished polymer are balanced by acetate ions.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"7bdb45a0-eabc-4cd4-be43-6df7738a081f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SILICONE QUATERNIUM-27"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Silicone Quaternium-27 is a complex silicone polymer that is made in several steps. First, Glycidoxy Dimethicone is reacted with dimethylamine. The resulting siloxane polymer is then quaternized by reacting the tertiary amine groups created in the previous step with a glycidoxy-terminated polypropylene glycol that contains an average of seven mols of polypropylene oxide. Finally, additional quaternary ammonium groups are created on the silicone polymer by reacting epoxy groups left over from the previous step with dodecyldimethyl amine. The last two reactions are done in the presence of acetic acid so that the positive charges on the finished polymer are balanced by acetate ions."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F6B877EE7C8B69A85BFFC0EB4ECAC2CB"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SILICONE QUATERNIUM-27"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93238"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:43:39.599+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:43:39.559+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"7bdb45a0-eabc-4cd4-be43-6df7738a081f. Available at: urn:test"}'::jsonb),
