  (93299, 'b0640b1f-2824-404d-a047-3bf09293109a'::uuid, 'METHIONYL R-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40', 'METHIONYL R-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40', NULL, NULL, NULL, 'Methionyl r-Clostridium Botulinum Polypeptide-1 Hexapeptide-40 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from r-Clostridium Botulinum Polypeptide-1 and Hexapeptide-40 with the initiation codon for methionine. The fusion peptide contains 469 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b0640b1f-2824-404d-a047-3bf09293109a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL R-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl r-Clostridium Botulinum Polypeptide-1 Hexapeptide-40 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from r-Clostridium Botulinum Polypeptide-1 and Hexapeptide-40 with the initiation codon for methionine. The fusion peptide contains 469 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],