  (93312, 'f751faee-d8f5-4a83-9000-cd1e370889cd'::uuid, 'METHIONYL HEXAPEPTIDE-40 SH-DECAPEPTIDE-1 TRIPEPTIDE-44 RH-OLIGOPEPTIDE-1', 'METHIONYL HEXAPEPTIDE-40 SH-DECAPEPTIDE-1 TRIPEPTIDE-44 RH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'Methionyl Hexapeptide-40 sh-Decapeptide-1 Tripeptide-44 rh-Oligopeptide-1 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from Hexapeptide-40, sh-Decapeptide-1 , Tripeptide-44 and rh-Oligopeptide-1 with the initiation code for methionine. The fusion peptide contains 73 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f751faee-d8f5-4a83-9000-cd1e370889cd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL HEXAPEPTIDE-40 SH-DECAPEPTIDE-1 TRIPEPTIDE-44 RH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl Hexapeptide-40 sh-Decapeptide-1 Tripeptide-44 rh-Oligopeptide-1 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from Hexapeptide-40, sh-Decapeptide-1 , Tripeptide-44 and rh-Oligopeptide-1 with the initiation code for methionine. The fusion peptide contains 73 amino acids and consists of the proper sequence of the 20 standard amino acids."],"e