  (93313, '66e5eb81-7d14-4696-ba36-c5eb5f2a8943'::uuid, 'METHIONYL HEXAPEPTIDE-40 SH-DECAPEPTIDE-1 RH-POLYPEPTIDE-50', 'METHIONYL HEXAPEPTIDE-40 SH-DECAPEPTIDE-1 RH-POLYPEPTIDE-50', NULL, NULL, NULL, 'Methionyl Hexapeptide-40 sh-Decapeptide-1 rh-Polypeptide-50 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from Hexapeptide-40 (q.v.), sh-Decapeptide-1, and rh-Polypeptide-50 with the initiation codon for methionine. The fusion peptide contains 99 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"66e5eb81-7d14-4696-ba36-c5eb5f2a8943","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL HEXAPEPTIDE-40 SH-DECAPEPTIDE-1 RH-POLYPEPTIDE-50"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl Hexapeptide-40 sh-Decapeptide-1 rh-Polypeptide-50 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from Hexapeptide-40 (q.v.), sh-Decapeptide-1, and rh-Polypeptide-50 with the initiation codon for methionine. The fusion peptide contains 99 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"