  (93329, 'e2788c64-d32f-4b33-bb11-d9a87edb807f'::uuid, 'POLYURETHANE-63', 'POLYURETHANE-63', NULL, NULL, NULL, 'Polyurethane-63 is a complex polymer formed by first reacting dimethylolpropionic acid (DMPA) and isophorone diisocyanate (IPDI) with a polyester diol made with Adipic Acid, isophthalic acid, and Hexanediol. The resulting prepolymer is then neutralized with triethylamine and finally, chain-extended with ethylenediamine.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"e2788c64-d32f-4b33-bb11-d9a87edb807f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-63"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-63 is a complex polymer formed by first reacting dimethylolpropionic acid (DMPA) and isophorone diisocyanate (IPDI) with a polyester diol made with Adipic Acid, isophthalic acid, and Hexanediol. The resulting prepolymer is then neutralized with triethylamine and finally, chain-extended with ethylenediamine."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["A9C57E90FD6C1B377CDAE2662235A5DF"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-63"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93329"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text