  (93333, '23b199f6-ec98-4e7b-b9aa-df1031c3a005'::uuid, '3-HYDROXYBUTYRATE/3-HYDROXYHEXANOATE COPOLYMER', '3-HYDROXYBUTYRATE/3-HYDROXYHEXANOATE COPOLYMER', NULL, NULL, NULL, '3-Hydroxybutyrate/3-Hydroxyhexanoate Copolymer is a polymer of 3-hydroxybutyrate and 3-hydroxyhexanoate which may be produced through the biofermentation of plant oils.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"23b199f6-ec98-4e7b-b9aa-df1031c3a005","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.583256,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["3-HYDROXYBUTYRATE/3-HYDROXYHEXANOATE COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["3-Hydroxybutyrate/3-Hydroxyhexanoate Copolymer is a polymer of 3-hydroxybutyrate and 3-hydroxyhexanoate which may be produced through the biofermentation of plant oils."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["120508AF4CA8B818B14641B59526C01C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["3-HYDROXYBUTYRATE/3-HYDROXYHEXANOATE COPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93333"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ABRASIVE"],"esDA_IngestDate":["2023-05-22T16:42:32.702+0200"],"currentVersion":[],"corporate-search-