  (93334, 'd5d42731-bd1e-4093-b3bb-719809e742a1'::uuid, 'POLYURETHANE-64', 'POLYURETHANE-64', NULL, NULL, NULL, 'Polyurethane-64 is a urethane copolymer formed by a multi-step reaction. First, isophorone diisocyanate (IDPI) is reacted with a mixture of polytetrahydrofurans (PTHFs), also known as polybutylene glycols or polytetramethylene glycols. One of the PTHFs contains an average of 14 mols and the other an average of 28 mols of butylene glycol. The resulting polyurethane is reacted with 4,4''-methylenebis(cyclohexylamine) and finally the residual isocyanate groups are reacted with ethanol.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"d5d42731-bd1e-4093-b3bb-719809e742a1","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-64"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-64 is a urethane copolymer formed by a multi-step reaction. First, isophorone diisocyanate (IDPI) is reacted with a mixture of polytetrahydrofurans (PTHFs), also known as polybutylene glycols or polytetramethylene glycols. One of the PTHFs contains an average of 14 mols and the other an average of 28 mols of butylene glycol. The resulting polyurethane is reacted with 4,4''-methylenebis(cyclohexylamine) and finally the residual isocyanate groups are reacted with ethanol."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["6E555109DA834AE5A5C7F8A836ADAF89"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-64"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93334"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["FILM FORMING"],"esDA_IngestDate":["2023-05-22T16:41:50.257+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:41:50.234+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"d5d42731-bd1e-4093-b3bb-719809e742a1. Available at: urn:test"}'::jsonb),
