  (93530, 'ab9ed30e-99da-43c0-9581-f33d0f8d96bc'::uuid, 'TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-2 DIPEPTIDE-34 SH-POLYPEPTIDE-11 DIPEPTIDE-19 OLIGOPEPTIDE-91', 'TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-2 DIPEPTIDE-34 SH-POLYPEPTIDE-11 DIPEPTIDE-19 OLIGOPEPTIDE-91', NULL, NULL, NULL, 'Tripeptide-46 Hexapeptide-40 Decapeptide-27 Methionyl Oligopeptide-91 Dipeptide-19 sh-Polypeptide-2 Dipeptide-34 sh-Polypeptide-11 Dipeptide-19 Oligopeptide-91 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from Tripeptide-46 , Hexapeptide-40, Decapeptide-27, Oligopeptide-91, Dipeptide-19, sh-Polypeptide-2, Dipeptide-34, sh-Polypeptide-11 , Dipeptide-19, and Oligopeptide-91 with the amino acid code for Methionine . The fusion peptide contains 314 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ab9ed30e-99da-43c0-9581-f33d0f8d96bc","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-2 DIPEPTIDE-34 SH-POLYPEPTIDE-11 DIPEPTIDE-19 OLIGOPEPTIDE-91"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tripeptide-46 Hexapeptide-40 Decapeptide-27 Methionyl Oligopeptide-91 Dipeptide-19 sh-Polypeptide-2 Dipeptide-34 sh-Polypeptide-11 Dipeptide-19 Oligopeptide-91 is a single chain recombinant fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from Tripeptide-46 , Hexapeptide-40, Decapeptide-27, Oligopeptide-91, Dipeptide-19, sh-Polypeptide-2, Dipeptide-34, sh-Polypeptide-11 , Dipeptide-19, and Oligopeptide-91 with the amino acid code for Methionine . The fusion peptide contains 314 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D6B6662C6D5AAA5AA9BE8109D3614178"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-2 DIPEPTIDE-34 SH-POLYPEPTIDE-11 DIPEPTIDE-19 OLIGOPEPTIDE-91"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93530"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:41:43.041+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:41:43.005+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"ab9ed30e-99da-43c0-9581-f33d0f8d96bc. Available at: urn:test"}'::jsonb),
