  (93634, '5b6407a7-ce72-41ec-b8f8-74dc037fa283'::uuid, 'SH-POLYPEPTIDE-85', 'SH-POLYPEPTIDE-85', NULL, NULL, 'FGF9', 'sh-Polypeptide-85 is a single chain synthetic human peptide produced by fermentation in  E. coli.  The starting gene is a synthesized copy of the human gene which codes for Fibroblast Growth Factor 9 used as such or adapted to the production host. It contains a maximum of 208 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5b6407a7-ce72-41ec-b8f8-74dc037fa283","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-85"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["FGF9"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-85 is a single chain synthetic human peptide produced by fermentation in  E. coli.  The starting gene is a synthesized copy of the human gene which codes for Fibroblast Growth Factor 9 used as such or adapted to the production host. It contains a maximum of 208 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["89B088274F372D18F9A46698E2B7DA0C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient