  (93680, 'cd578dc8-f9d3-4e03-ae16-30c84c807f6e'::uuid, 'BEHENYLCARBAMOYLPROPYL POLYSILSESQUIOXANE', 'BEHENYLCARBAMOYLPROPYL POLYSILSESQUIOXANE', NULL, NULL, 'Silsesquioxanes, 3-[[(docosyloxy)carbonyl]amino]propyl, hydroxy-terminated', 'Behenylcarbamoylpropyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the behenylcarbamoylpropyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"cd578dc8-f9d3-4e03-ae16-30c84c807f6e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.2987847,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BEHENYLCARBAMOYLPROPYL POLYSILSESQUIOXANE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Silsesquioxanes, 3-[[(docosyloxy)carbonyl]amino]propyl, hydroxy-terminated"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Behenylcarbamoylpropyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the behenylcarbamoylpropyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["16FA4FA19C625637E53A1C8C2F85AF67"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BEHENYLCARBAMOYLPROPYL POLYSILSESQUIOXANE"],"esST_FileName":["file.txt"],"casNo":["1638330-84-3"],"substanceId":["93680"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BULKING"],"esDA_IngestDate":["2023-05-22T16:40:45.404+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:40:45.379+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"cd578dc8-f9d3-4e03-ae16-30c84c807f6e. Available at: urn:test"}'::jsonb),
