  (93851, '9f3c5b30-1026-41f3-af85-7595ea6228e7'::uuid, 'SH-BARLEY SEED EXTRACT', 'SH-BARLEY SEED EXTRACT', NULL, NULL, 'Transgenic Barley Seed Extract', 'sh-Barley Seed Extract is the extract of the seeds of transgenic barley,  Hordeum vulgare  , obtained after the transient expression or stable insertion of a copy of a human gene into its DNA. The starting gene is synthesized to be identical to the gene which codes for Keratinocyte Growth Factor,  Pooideae.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9f3c5b30-1026-41f3-af85-7595ea6228e7","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-BARLEY SEED EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Transgenic Barley Seed Extract"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Barley Seed Extract is the extract of the seeds of transgenic barley,  Hordeum vulgare  , obtained after the transient expression or stable insertion of a copy of a human gene into its DNA. The starting gene is synthesized to be identical to the gene which codes for Keratinocyte Growth Factor,  Pooideae."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["FE776486C287B53F8A5570EAB80CFF4A"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-BARLEY SEED EXTRACT"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93851"],"annexNo":[],"p