  (93854, 'f82cbc2f-57f3-4780-9a81-5e83fb181391'::uuid, 'LACTOBACILLUS/RHODOPSEUDOMONAS/SACCHAROMYCES/MOLASSES/LAVENDER/THYMUS SERPYLLUM/CYMBOPOGON CITRATUS/PEPPERMINT/MELISSA OFFICINALIS/CHAMOMILLA RECUTITA FLOWER/BERGAMOT LEAF/SPEARMINT/ROSEMARY FERMENT FILTRATE', 'LACTOBACILLUS/RHODOPSEUDOMONAS/SACCHAROMYCES/MOLASSES/LAVENDER/THYMUS SERPYLLUM/CYMBOPOGON CITRATUS/PEPPERMINT/MELISSA OFFICINALIS/CHAMOMILLA RECUTITA FLOWER/BERGAMOT LEAF/SPEARMINT/ROSEMARY FERMENT FILTRATE', NULL, NULL, NULL, 'Lactobacillus/Rhodopseudomonas/Saccharomyces/Molasses/Lavender/Thymus Serpyllum/Cymbopogon Citratus/Peppermint/Melissa Officinalis/Chamomilla Recutita Flower/Bergamot Leaf/Spearmint/Rosemary Ferment Filtrate is a filtrate of the product obtained by the fermentation of Molasses, the leaves of  Citrus aurantium bergamia  (bergamot), the flowers of  Chamomilla recutita  , the whole plants of  Lavandula angustifolia  (lavender),  Thymus serpyllum  ,  Cymbopogon citratus  ,  Mentha piperita  (peppermint),  Melissa officinalis  ,  Mentha viridis  (spearmint), and  Rosmarinus officinalis  (rosemary) by the microorganisms,  Lactobacillus, Rhodopseudomonas  and  Saccharomyces.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f82cbc2f-57f3-4780-9a81-5e83fb181391","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["LACTOBACILLUS/RHODOPSEUDOMONAS/SACCHAROMYCES/MOLASSES/LAVENDER/THYMUS SERPYLLUM/CYMBOPOGON CITRATUS/PEPPERMINT/MELISSA OFFICINALIS/CHAMOMILLA RECUTITA FLOWER/BERGAMOT LEAF/SPEARMINT/ROSEMARY FERMENT FILTRATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"i